syntax:
ReturnType (*FunctionPointerName)(ParameterTypes); // Declaring a function pointer

// Assigning a function to a pointer
FunctionPointerName = &FunctionName; // or simply FunctionName

// Calling via function pointer
ResultType result = (*FunctionPointerName)(Arguments);

code_example:
typedef double (*PriceFunc)(void *context, int quantity);
struct Quote {
    PriceFunc net_price;
};
double base_net_price(void *context, int qty) {
    // context could be used for additional data
    return 100.0 * qty;
}
struct Quote quote_instance;
quote_instance.net_price = &base_net_price;
double price = quote_instance.net_price(NULL, 20); // Advanced callback invocation
